      const { object } = this.props;
      let layers = "";
      if (Array.isArray(object.layers)) {
        if (object.layers.length > 0) {
          layers = object.layers.map((l3) => `<canvas data-layer="${l3}"></canvas>`).join("");
        }
      } else {
        layers = '<canvas data-layer="base"></canvas>';
      }
