  // src/components/character-sprite/index.ts
  class CharacterSprite extends Component_default {
    static tag = "character-sprite";
    _resizeHandler = null;
    constructor() {
      super();
      this.props = {
        character: "",
        src: "",
        directory: "",
        width: 0,
        height: 0,
        ratio: 0
      };
      this.state = {
        layers: {}
      };
    }
    onStateUpdate(property, _oldValue, _newValue) {
      if (property === "layers") {
        return this.forceRender().then(() => {
          this.resize();
          return Promise.resolve();
        });
      }
      return Promise.resolve();
    }
    onPropsUpdate(property, _oldValue, newValue, _oldObject, newObject) {
      if (property === "src") {
        if (typeof newValue === "string" && newValue.trim() !== "") {
          const img = document.createElement("img");
          img.src = newValue;
          this.element().find("img:not(:first-child)").each((element) => {
            element.remove();
          });
          const firstImg = this.element().find("img").get(0);
          if (firstImg) {
            firstImg.setAttribute("src", newValue);
          }
        }
      }
      if (property === "width" || property === "height") {
        const { height, width } = newObject;
        this.content("wrapper").style({
          height: `max(${height}px, 80vh)`,
          width: `max(${width}px, 80vh)`
        });
      }
      return Promise.resolve();
    }
    willMount() {
      return Promise.resolve();
    }
    didMount() {
      this._resizeHandler = () => {
        this.resize();
      };
      window.addEventListener("resize", this._resizeHandler);
      this.resize();
      return Promise.resolve();
    }
    willUnmount() {
      if (this._resizeHandler) {
        window.removeEventListener("resize", this._resizeHandler);
        this._resizeHandler = null;
      }
      return Promise.resolve();
    }
    resize() {
      const { width, height, ratio } = this.props;
      const actualHeight = parseInt(getComputedStyle(this).height.replace("px", ""));
      const realWidth = actualHeight * ratio;
      this.content("wrapper").style({
        width: `${realWidth}px`
      });
      this.content("wrapper").find("[data-layer]").each((layer) => {
        const layerEl = layer;
        layerEl.onload = () => {
          if (layerEl.naturalWidth !== width) {
            layerEl.style.width = `${layerEl.naturalWidth * realWidth / width}px`;
          }
          if (layerEl.naturalHeight !== height) {
            layerEl.style.height = "auto";
          }
        };
      });
    }
    render() {
      const { character: character2, directory } = this.props;
      if (typeof character2 === "string") {
        return Promise.resolve('<div data-content="wrapper"></div>');
      }
      const promises = [];
      for (const layer of character2.layers) {
        const localLayer = this.state.layers[layer];
        if (typeof localLayer === "object" && localLayer !== null) {
          const { classes } = localLayer;
          let asset2 = localLayer.asset;
          if (typeof character2.layer_assets === "object" && character2.layer_assets !== null) {
            const layerAssets = character2.layer_assets[layer];
            if (typeof layerAssets === "object" && layerAssets !== null) {
              if (typeof layerAssets[asset2] === "string") {
                asset2 = layerAssets[asset2];
              }
            }
          }
          if (typeof asset2 === "string") {
            promises.push(new Promise((resolve) => {
              const image = new Image;
              image.src = `${directory}${asset2}`;
              image.onload = function() {
                resolve({ layer, image, classes, sprite: localLayer.asset });
              };
            }));
          }
        }
      }
      return Promise.all(promises).then((assets2) => {
        return new Promise((resolve) => {
          const wrapper = document.createElement("div");
          wrapper.dataset.content = "wrapper";
          let maxHeight = 0;
          let maxWidth = 0;
          for (const asset2 of assets2) {
            const { image, layer, classes, sprite } = asset2;
            const height = image.naturalHeight;
            const width = image.naturalWidth;
            if (height > maxHeight) {
              maxHeight = height;
            }
            if (width > maxWidth) {
              maxWidth = width;
            }
            image.style.zIndex = String(character2.layers.indexOf(layer));
            image.dataset.layer = layer;
            image.dataset.sprite = sprite;
            image.classList.add(...classes);
            wrapper.appendChild(image);
          }
          this.setProps({
            ratio: maxWidth / maxHeight,
            height: maxHeight,
            width: maxWidth
          });
          wrapper.style.height = `${maxHeight}px`;
          resolve(wrapper.outerHTML);
        });
      });
    }
  }
  var character_sprite_default = CharacterSprite;

  // src/components/choice-container/index.ts
  class ChoiceContainer extends Component_default {
    static tag = "choice-container";
    constructor() {
      super();
      this.props = {
        choices: [],
        classes: ""
      };
    }
    shouldProceed() {
      return Promise.reject("Choice Container awaiting for user input.");
    }
    willRollback() {
      this.remove();
      return Promise.resolve();
    }
    onReset() {
      this.remove();
      return Promise.resolve();
    }
    willMount() {
      if (typeof this.props.classes === "string" && this.props.classes !== "") {
        this.props.classes.split(" ").forEach((className) => {
          if (className) {
            this.classList.add(className);
          }
        });
      }
      return Promise.resolve();
    }
    didMount() {
      return Promise.resolve();
    }
    render() {
      const choices = this.props.choices.map((choice) => {
        const choiceText = this.engine.replaceVariables(choice.Text);
        if (typeof choice.Clickable === "function") {
          return new Promise((resolve) => {
            this.engine.assertAsync(choice.Clickable, this.engine).then(() => {
              resolve(`<button data-do="${choice.Do}" ${choice.Class ? `class="${choice.Class}"` : ""} data-choice="${choice._key}">${choiceText}</button>`);
            }).catch(() => {
              resolve(`<button data-do="${choice.Do}" ${choice.Class ? `class="${choice.Class}"` : ""} data-choice="${choice._key}" disabled>${choiceText}</button>`);
            });
          });
        }
        return Promise.resolve(`<button data-do="${choice.Do}" ${choice.Class ? `class="${choice.Class}"` : ""} data-choice="${choice._key}">${choiceText}</button>`);
      });
      return Promise.all(choices).then((choiceButtons) => `
			<div data-content="wrapper">
				${choiceButtons.join("")}
			</div>
		`);
    }
  }
