  // src/components/language-selection-screen/index.ts
  class LanguageSelectionScreen extends ScreenComponent_default {
    static tag = "language-selection-screen";
    timer = null;
    constructor() {
      super();
      this.props = {
        languages: Object.keys(this.engine._script),
        timeout: 2000
      };
      this.state = {
        open: false,
        index: 0
      };
    }
    onStateUpdate(property, oldValue, newValue) {
      super.onStateUpdate(property, oldValue, newValue);
      if (property === "index") {
        const { languages } = this.props;
        const translation2 = this.engine.translation(languages[newValue]);
        if (typeof translation2 === "object" && translation2 !== null) {
          const translationObj = translation2;
          const string2 = translationObj.SelectYourLanguage;
          if (typeof string2 === "string") {
            this.content("title").text(string2);
          }
        }
      }
      return Promise.resolve();
    }
    didMount() {
      if (this.engine.setting("MultiLanguage") === true && this.engine.setting("LanguageSelectionScreen") === true) {
        const { languages, timeout } = this.props;
        this.timer = setTimeout(() => {
          if (this.element().isVisible()) {
            const { index: index2 } = this.state;
            if (index2 >= languages.length - 1) {
              this.setState({ index: 0 });
            } else {
              this.setState({ index: index2 + 1 });
            }
            this.timer = setTimeout(() => this.didMount(), parseInt(String(timeout)));
          } else {
            if (this.timer) {
              clearTimeout(this.timer);
            }
          }
        }, parseInt(String(timeout)));
      }
      this.element().on("click", "[data-language]", (event) => {
        const language = u(event.target).closest("[data-language]").data("language");
        if (language) {
          this.engine.preference("Language", language);
          this.engine.localize();
        }
      });
      return Promise.resolve();
    }
    willUnmount() {
      if (this.timer) {
        clearTimeout(this.timer);
        this.timer = null;
      }
      return Promise.resolve();
    }
    render() {
      let buttons = [];
      if (this.engine.setting("MultiLanguage") === true && this.engine.setting("LanguageSelectionScreen") === true) {
        const { languages } = this.props;
        buttons = languages.map((language) => {
          const metadata = this.engine._languageMetadata[language];
          if (typeof metadata === "object") {
            const { icon } = metadata;
            return `
						<button data-language="${language}" title="${language}">
							${typeof icon === "string" ? `<span data-content="icon">${icon}</span>` : ""}
							<span data-content="language">${language}</span>
						</button>
					`;
          } else {
            FancyError.show("component:language_selection_screen:metadata_not_found", {
              language,
              availableLanguages: Object.keys(this.engine._script)
            });
            return "";
          }
        }).filter(Boolean);
      }
      return `
			<div data-content="wrapper">
				<h1 data-content="title" data-string="SelectYourLanguage">${this.engine.string("SelectYourLanguage")}</h1>
				<div data-content="buttons">
					${buttons.join("")}
				</div>
			</div>
		`;
    }
  }
  var language_selection_screen_default = LanguageSelectionScreen;

