  // src/lib/MenuComponent.ts
  class MenuComponent extends Component_default {
    static tag = "menu-component";
    static addButton(button) {
      this.engine.configuration(this.tag, {
        buttons: [...this.buttons(), button]
      });
      this.onConfigurationUpdate();
    }
    static addButtonAfter(after, button) {
      const index2 = this.buttons().findIndex((b3) => b3.string === after);
      const buttons = [...this.buttons()];
      if (index2 > -1) {
        buttons.splice(index2 + 1, 0, button);
        this.engine.configuration(this.tag, {
          buttons
        });
        this.onConfigurationUpdate();
      }
    }
    static addButtonBefore(before, button) {
      const index2 = this.buttons().findIndex((b3) => b3.string === before);
      const buttons = [...this.buttons()];
      if (index2 > -1) {
        buttons.splice(index2, 0, button);
        this.engine.configuration(this.tag, {
          buttons
        });
        this.onConfigurationUpdate();
      }
    }
    static removeButton(string2) {
      this.engine.configuration(this.tag, {
        buttons: this.buttons().filter((button) => button.string !== string2)
      });
      this.onConfigurationUpdate();
    }
    static buttons() {
      const config = this.engine.configuration(this.tag);
      return config.buttons;
    }
    static button(string2) {
      return this.buttons().find((button) => button.string === string2);
    }
    static async onConfigurationUpdate() {
      const elements = document.querySelectorAll(this.tag);
      for (const element of elements) {
        if (element instanceof Component_default) {
          element.innerHTML = element.render();
        }
      }
    }
    render() {
      const staticContext = this.constructor;
      return staticContext.buttons().map((button) => {
        if (typeof button.element !== "string") {
          button.element = "button";
        }
        const element = document.createElement(button.element);
        if (typeof button.data === "object") {
          for (const key of Object.keys(button.data)) {
            element.dataset[key] = button.data[key];
          }
        }
        element.setAttribute("icon", button.icon);
        element.setAttribute("string", button.string);
        return element.outerHTML;
      }).join(" ");
    }
  }

